31	    /**
32	     * Specification to fetch Posts belonging to a Conversation
33	     *
34	     * @param conversationId id of the conversation the Posts belong to
35	     * @return specification used to chain DB operations
36	     */
37	    public static Specification<Post> getConversationSpecification(Long conversationId) {
38	        return ((root, query, criteriaBuilder) -> criteriaBuilder.equal(root.get(Post_.CONVERSATION).get(Conversation_.ID), conversationId));
39	    }
40	
41	    /**
42	     * Specification which filters Messages and answer posts according to a search string in a match-all-manner
43	     * message and answer post are only kept if the search string (which is not a #id pattern) is included in the message content (all strings lowercased)
44	     *
45	     * @param searchText Text to be searched within messages
46	     * @return specification used to chain DB operations
47	     */
48	    public static Specification<Post> getSearchTextSpecification(String searchText) {
49	        return ((root, query, criteriaBuilder) -> {
50	            if (searchText == null || searchText.isBlank()) {
51	                return null;
52	            }
53	            // search by text or #message
54	            else if (searchText.startsWith("#") && StringUtils.isNumeric(searchText.substring(1))) {
55	                // if searchText starts with a # and is followed by a message id, filter for message with id
56	                return criteriaBuilder.equal(root.get(Post_.ID), Integer.parseInt(searchText.substring(1)));
57	            }
58	            else {
59	                // regular search on content
60	                Expression<String> searchTextLiteral = criteriaBuilder.literal("%" + searchText.toLowerCase() + "%");
61	
62	                Predicate searchInMessageContent = criteriaBuilder.like(criteriaBuilder.lower(root.get(Post_.CONTENT)), searchTextLiteral);
63	                Join<Post, AnswerPost> answersJoin = root.join(Post_.ANSWERS, JoinType.LEFT);
64	                Predicate searchInAnswerContent = criteriaBuilder.like(criteriaBuilder.lower(answersJoin.get(AnswerPost_.CONTENT)), searchTextLiteral);
65	
66	                return criteriaBuilder.or(searchInMessageContent, searchInAnswerContent);
67	            }
68	        });
69	    }
